import unittest,numpy as np
from sklearn.preprocessing import StandardScaler
from support_l1 import SupportView,fit_head,kkt_diagnostic
class SupportL1Test(unittest.TestCase):
    def test_query_rows_cannot_be_read(self):
        data={'labels':np.array([0,0,1,1,1,0]),'covariates':np.arange(12.).reshape(6,2)}
        v=SupportView(data,[0,1,2,3,4],[5])
        with self.assertRaises(AssertionError):v.rows('covariates',[0,5])
        with self.assertRaises(AssertionError):v.rows('labels',[5])
        np.testing.assert_array_equal(v.rows('covariates',[1,3]),data['covariates'][[1,3]])
    def test_strong_l1_has_known_zero_solution(self):
        x=np.array([[-2.,1],[-1.,2],[0.,3],[1.,4],[2.,5]]);y=np.array([0,0,1,1,1]);w=np.array([.25,.25,1/6,1/6,1/6]);scaler=StandardScaler().fit(x,sample_weight=w)
        h=fit_head(x,x,y,y,w,scaler,10.)
        self.assertEqual(h['diagnostic']['nonzero_coefficients'],0);self.assertFalse(h['diagnostic']['nonzero_intercept'])
        np.testing.assert_array_equal(h['probability'],np.full(5,.5));self.assertAlmostEqual(h['diagnostic']['objective'],np.log(2));self.assertEqual(h['diagnostic']['maximum_kkt_residual'],0)
    def test_kkt_detects_wrong_nonzero_solution(self):
        x=np.arange(10.).reshape(5,2);y=np.array([0,0,1,1,1]);w=np.array([.25,.25,1/6,1/6,1/6]);scaler=StandardScaler().fit(x,sample_weight=w);h=fit_head(x,x,y,y,w,scaler,10.)
        h['model'].coef_[0,0]=1
        self.assertGreater(kkt_diagnostic(scaler.transform(x),y,w,h['model'],10.)['maximum_kkt_residual'],9)
if __name__=='__main__':unittest.main()
